237	    /**
238	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
239	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
240	     * Validation already rejects {@code null} values and the pattern-constrained fields
241	     * when blank, but {@code address} and {@code city} have no pattern, so a
242	     * whitespace-only value would otherwise slip through.
243	     *
244	     * @param ownerFieldsDto the submitted owner fields
245	     * @throws RequiredFieldsMissingException if any required field is missing or blank
246	     */
247	    /**
248	     * Common street-type abbreviations expanded during address normalization. Keys are the
249	     * upper-cased abbreviation tokens; values are their canonical expansions.
250	     */
251	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
252	        "ST", "STREET",
253	        "RD", "ROAD",
254	        "AVE", "AVENUE");
255	
256	    /**
257	     * Normalizes the submitted address on create and writes the canonical value back onto the
258	     * request so it is persisted, echoed back, and used for every downstream address comparison
259	     * (household duplicate detection and the household id). The value is trimmed, internal
260	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
261	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
262	     * {@code null} address is left untouched so the required-field check can report it as missing.
263	     *
264	     * @param ownerFieldsDto the submitted owner fields
265	     */
266	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
267	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
268	    }
269	
270	    /**
271	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
272	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
273	     * expanded to its full form. A {@code null} value is returned unchanged.
274	     *
275	     * @param raw the address to canonicalize, possibly {@code null}
276	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
277	     */
278	    private static String normalizeAddress(String raw) {
279	        if (raw == null) {
280	            return null;
281	        }
282	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
283	        if (collapsed.isEmpty()) {
284	            return collapsed;
285	        }
286	        String[] tokens = collapsed.split(" ");
287	        StringBuilder sb = new StringBuilder(collapsed.length());
288	        for (int i = 0; i < tokens.length; i++) {
289	            if (i > 0) {
290	                sb.append(' ');
291	            }
292	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
293	        }
294	        return sb.toString();
295	    }
296	
297	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
298	        List<String> errors = new ArrayList<>();
299	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
300	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
301	        requireText("address", ownerFieldsDto.getAddress(), errors);
302	        requireText("city", ownerFieldsDto.getCity(), errors);
303	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
304	        if (!errors.isEmpty()) {
305	            throw new RequiredFieldsMissingException(errors);
306	        }
307	    }
308	
309	    private static void requireText(String field, String value, List<String> errors) {
310	        if (value == null || value.isBlank()) {
311	            errors.add(field);
312	        }
313	    }
314	
315	    /**
316	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
317	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
318	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
319	     */
320	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
321	        "NSW", new int[] {2000, 2099},
322	        "VIC", new int[] {3000, 3099},
323	        "QLD", new int[] {4000, 4099});
324	
325	    /**
326	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
327	     * {@code null} value is accepted. When present it has already been constrained to four digits
328	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
329	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
330	     * the postcode must fall within that region's inclusive range
331	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
332	     *
333	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
334	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
335	     *                                  city's region
336	     */
337	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
338	        String postcode = ownerFieldsDto.getPostcode();
339	        if (postcode == null) {
340	            return;
341	        }
342	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
343	            .regionFor(ownerFieldsDto.getCity());
344	        int[] range = REGION_POSTCODE_RANGE.get(region);
345	        if (range == null) {
346	            return;
347	        }
348	        int value = Integer.parseInt(postcode);
349	        if (value < range[0] || value > range[1]) {
350	            throw new InvalidPostcodeException(postcode);
351	        }
352	    }
353	
354	    /**
355	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
356	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
357	     * and echoed back in that form.
358	     *
359	     * @param ownerFieldsDto the submitted owner fields
360	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
361	     *                                        valid E.164 number
362	     */
363	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
364	        String e164 = toE164(ownerFieldsDto.getTelephone());
365	        if (e164 == null) {
366	            throw new RequiredFieldsMissingException(List.of("telephone"));
367	        }
368	        ownerFieldsDto.setTelephone(e164);
369	    }
370	
371	    /**
372	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
373	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
374	     * and country code are present they are kept; otherwise country code {@code '+61'} is
375	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
376	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
377	     * the national-number length must match the country: {@code '+61'} (Australia) requires
378	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
379	     *
380	     * @param raw the submitted telephone, possibly {@code null}
381	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
382	     */
383	    private static String toE164(String raw) {
384	        if (raw == null) {
385	            return null;
386	        }
387	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
388	        String digits;
389	        if (cleaned.startsWith("+")) {
390	            digits = cleaned.substring(1);
391	        } else {
392	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
393	            digits = "61" + national;
394	        }
395	        if (!digits.matches("[0-9]{8,15}")) {
396	            return null;
397	        }
398	        if (digits.startsWith("61")) {
399	            // Australia: exactly 9 national digits after the '+61' country code.
400	            if (digits.length() - 2 != 9) {
401	                return null;
402	            }
403	        } else if (digits.startsWith("1")) {
404	            // NANP: exactly 10 national digits after the '+1' country code.
405	            if (digits.length() - 1 != 10) {
406	                return null;
407	            }
408	        }
409	        return "+" + digits;
410	    }
411	
412	    /**
413	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
414	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
415	     * each stored owner's telephone is normalized the same way before comparison so differing
416	     * input formats collapse to the same value.
417	     *
418	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
419	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
420	     *                                     same E.164 telephone
421	     */
422	    /**
423	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
424	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
425	     * the parts may contain whitespace or a second {@code @}.
426	     */
427	    private static final Pattern EMAIL_PATTERN =
428	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
429	
430	    /**
431	     * Normalizes the submitted email when present: the value is trimmed, required to be a
432	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
433	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
434	     *
435	     * @param ownerFieldsDto the submitted owner fields
436	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
437	     */
438	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
439	        String email = ownerFieldsDto.getEmail();
440	        if (email == null) {
441	            return;
442	        }
443	        String trimmed = email.strip();
444	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
445	            throw new InvalidEmailException(email);
446	        }
447	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
448	    }
449	
450	    /**
451	     * Rejects a create whose supplied {@code registrationDate} is later than the server's current
452	     * date. A registration may be back-dated but never post-dated. The check is made against the
453	     * value as supplied, before any defaulting or business-day roll (see
454	     * {@link #defaultRegistrationDate}); a {@code null} registration date is accepted (it defaults
455	     * to the server date).
456	     *
457	     * @param ownerFieldsDto the submitted owner fields
458	     * @throws FutureRegistrationDateException with a 400 status if the supplied registration date is
459	     *                                         after the server's current date
460	     */
461	    private static void rejectFutureRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
462	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
463	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
464	            throw new FutureRegistrationDateException(supplied);
465	        }
466	    }
467	
468	    /**
469	     * Establishes the effective registration date on create and rolls it onto a business day.
470	     * When the client does not supply a {@code registrationDate} it defaults to the server's
471	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
472	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
473	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
474	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
475	     * the membership number's year segment and the daily create-limit).
476	     *
477	     * @param ownerFieldsDto the submitted owner fields
478	     */
479	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
480	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
481	        if (effective == null) {
482	            effective = LocalDate.now();
483	        }
484	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
485	    }
486	
487	    /**
488	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
489	     * following Monday; any weekday is returned unchanged.
490	     *
491	     * @param date the date to adjust
492	     * @return the same date when it is a weekday, otherwise the next Monday
493	     */
494	    private static LocalDate toBusinessDay(LocalDate date) {
495	        return switch (date.getDayOfWeek()) {
496	            case SATURDAY -> date.plusDays(2);
497	            case SUNDAY -> date.plusDays(1);
498	            default -> date;
499	        };
500	    }
501	
502	    /**
503	     * Assigns the owner's {@code customerCode} on create, formatted
504	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
505	     * (preferring the postcode range, falling back to the city — the same derivation that yields
506	     * the owner's {@code locality}, see
507	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
508	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
509	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
510	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
511	     * customer code only when their normalized telephone and last name both match.
512	     *
513	     * @param owner the owner being created (with its {@code postcode}, {@code city},
514	     *              {@code telephone} and {@code lastName} already set)
515	     */
516	    private void assignCustomerCode(Owner owner) {
517	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
518	            .regionFor(owner.getPostcode(), owner.getCity());
519	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
520	            .substring(0, 8).toUpperCase(Locale.ROOT);
521	        owner.setCustomerCode(region + "-" + hash8);
522	    }
523	
524	    /**
525	     * Assigns the owner's {@code householdId} on create: a stable, deterministic identifier for
526	     * the household, the first 12 hex characters of the SHA-256 digest of the owner's normalized
527	     * {@code lastName} and {@code postcode} (see {@link #householdIdFor}). Because it is derived
528	     * purely from those two fields, every owner sharing a last name and postcode is assigned the
529	     * same value automatically — including one joining an existing household via
530	     * {@code sharesHousehold} — independent of create order.
531	     *
532	     * @param owner the owner being created (with its {@code lastName} and {@code postcode} already set)
533	     */
534	    private void assignHouseholdId(Owner owner) {
535	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
536	    }
537	
538	    /**
539	     * Derives the deterministic {@code householdId} for the given {@code lastName} and
540	     * {@code postcode}: the first 12 hex characters of the SHA-256 digest of the normalized
541	     * {@code lastName} (see {@link #collapse}) concatenated with a {@code '|'} and the
542	     * {@code postcode} (empty when absent). Because it is derived purely from those two fields,
543	     * every owner sharing a last name and postcode receives the same value, independent of create
544	     * order. Shared by {@link #assignHouseholdId} (which persists it), {@link #identityKeyFor}
545	     * (which folds it into the identity key for duplicate detection) and
546	     * {@link #rejectDuplicateHousehold} (which blocks a second owner in the same household).
547	     *
548	     * @param lastName the owner's last name
549	     * @param postcode the owner's postcode, possibly {@code null}
550	     * @return the derived household id
551	     */
552	    private static String householdIdFor(String lastName, String postcode) {
553	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
554	        return sha256Hex(key).substring(0, 12);
555	    }
556	
557	    /**
558	     * Rejects a create whose computed {@code householdId} (derived from {@code lastName} and
559	     * {@code postcode}, see {@link #householdIdFor}) already belongs to an existing owner, unless
560	     * the request opts in via {@code sharesHousehold}. Because the household is keyed on
561	     * {@code (lastName, postcode)}, a second owner sharing both is the same household: it is
562	     * rejected with a 409 as a household duplicate unless it declares {@code sharesHousehold}, in
563	     * which case it is created as a declared household member. The scan is taken over the existing
564	     * owners before this one is persisted.
565	     *
566	     * @param ownerFieldsDto the submitted owner fields ({@code lastName} and {@code postcode} set)
567	     * @throws DuplicateHouseholdException with a 409 status if the household already exists and the
568	     *                                     request did not opt in via {@code sharesHousehold}
569	     */
570	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
571	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
572	            return;
573	        }
574	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
575	        boolean duplicate = this.clinicService.findAllOwners().stream()
576	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
577	        if (duplicate) {
578	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
579	        }
580	    }
581	
582	    /**
583	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
584	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
585	     * after this create. Because {@code householdId} is derived from the owner's {@code lastName}
586	     * and {@code postcode} (see {@link #assignHouseholdId}), the count reflects every
587	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
588	     * The count is taken before this owner is persisted, so it is one more than the number of
589	     * existing household members.
590	     *
591	     * @param owner the owner being created (with its {@code householdId} already assigned)
592	     */
593	    private void assignHouseholdMemberCount(Owner owner) {
594	        String householdId = owner.getHouseholdId();
595	        long existing = this.clinicService.findAllOwners().stream()
596	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
597	            .count();
598	        owner.setHouseholdMemberCount((int) (existing + 1));
599	    }
600	
601	    /**
602	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
603	     * already share this owner's {@code firstName} and {@code lastName}, compared
604	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
605	     * pre-existing namesakes.
606	     *
607	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
608	     */
609	    private void assignNamesakeCount(Owner owner) {
610	        String firstName = owner.getFirstName();
611	        String lastName = owner.getLastName();
612	        long count = this.clinicService.findAllOwners().stream()
613	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
614	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
615	            .count();
616	        owner.setNamesakeCount((int) count);
617	    }
618	
619	    /**
620	     * Assigns the owner's {@code membershipNumber} on create, formatted
621	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
622	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
623	     * (e.g. {@code 'NSW-A1B2C3D4-M26'}). Derived purely from the owner's own fields, so both
624	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
625	     *
626	     * @param owner the owner being created (with its {@code customerCode} and
627	     *              {@code registrationDate} already set)
628	     */
629	    private void assignMembershipNumber(Owner owner) {
630	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
631	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
632	    }
633	
634	    /**
635	     * The number of owners that must already carry a registration date before a subsequent
636	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
637	     * once the count of owners already registered on that day <em>exceeds</em> this value.
638	     */
639	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
640	
641	    /**
642	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
643	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
644	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
645	     * existing owners before this one is persisted, so it reflects only the owners already
646	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
647	     *
648	     * @param owner the owner being created (with its {@code registrationDate} already set)
649	     */
650	    private void assignBulkSignupWarning(Owner owner) {
651	        LocalDate registrationDate = owner.getRegistrationDate();
652	        long count = this.clinicService.findAllOwners().stream()
653	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
654	            .count();
655	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
656	    }
657	
658	    /**
659	     * Assigns the owner's soft-match duplicate flags on create. The create has already passed
660	     * {@link #rejectDuplicateIdentity} and {@link #rejectDuplicateHousehold}, so this owner is not
661	     * a hard duplicate. A declared household member (one that opted in via {@code sharesHousehold})
662	     * is never flagged: it is an acknowledged member of the household, not a suspected duplicate,
663	     * so {@code possibleDuplicate} is {@code false}. Otherwise it is a <em>possible</em> duplicate
664	     * when an existing owner shares its {@code lastName} (compared case-insensitively) and its
665	     * {@code postcode} but has a <em>different</em> normalized {@code telephone}:
666	     * {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to that owner's
667	     * id (the earliest such owner by id when several match). Otherwise {@code possibleDuplicate} is
668	     * {@code false} and {@code possibleDuplicateOf} is left unset. The scan is taken over the
669	     * existing owners before this one is persisted.
670	     *
671	     * @param owner the owner being created (with its {@code lastName}, {@code postcode} and
672	     *              already-normalized {@code telephone} set)
673	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
674	     */
675	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
676	        if (declaredHouseholdMember) {
677	            owner.setPossibleDuplicate(false);
678	            owner.setPossibleDuplicateOf(null);
679	            return;
680	        }
681	        String lastName = owner.getLastName();
682	        String postcode = owner.getPostcode();
683	        String telephone = owner.getTelephone();
684	        Integer matchId = null;
685	        if (lastName != null && postcode != null && telephone != null) {
686	            matchId = this.clinicService.findAllOwners().stream()
687	                .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
688	                .filter(existing -> postcode.equals(existing.getPostcode()))
689	                .filter(existing -> !telephone.equals(existing.getTelephone()))
690	                .map(Owner::getId)
691	                .filter(id -> id != null)
692	                .min(Integer::compareTo)
693	                .orElse(null);
694	        }
695	        owner.setPossibleDuplicate(matchId != null);
696	        owner.setPossibleDuplicateOf(matchId);
697	    }
698	
699	    /**
700	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
701	     *
702	     * @param value the string to hash
703	     * @return the 64-character lower-case hex digest
704	     */
705	    private static String sha256Hex(String value) {
706	        try {
707	            byte[] digest = MessageDigest.getInstance("SHA-256")
708	                .digest(value.getBytes(StandardCharsets.UTF_8));
709	            StringBuilder sb = new StringBuilder(digest.length * 2);
710	            for (byte b : digest) {
711	                sb.append(String.format("%02x", b));
712	            }
713	            return sb.toString();
714	        }
715	        catch (NoSuchAlgorithmException e) {
716	            throw new IllegalStateException("SHA-256 not available", e);
717	        }
718	    }
719	
720	    /**
721	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
722	     * owner. This single key consolidates what used to be three separate duplicate checks
723	     * (telephone, email and household): the key is
724	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
725	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
726	     * matches an existing owner's. Because the telephone is part of the key, two members of the
727	     * same household (same {@code householdId}) with different telephones have different identity
728	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
729	     * and email have already been normalized by {@link #normalizeTelephone} and
730	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
731	     * input formats collapse to the same value.
732	     *
733	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
734	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
735	     *                                    whole identity key
736	     */
737	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
738	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(),
739	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
740	        boolean duplicate = this.clinicService.findAllOwners().stream()
741	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getPostcode(),
742	                owner.getTelephone(), owner.getEmail()))
743	            .anyMatch(identityKey::equals);
744	        if (duplicate) {
745	            throw new DuplicateIdentityException(identityKey);
746	        }
747	    }
748	
749	    /**
750	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
751	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
752	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
753	     * absent), and the {@code householdId} is derived from the {@code lastName} and
754	     * {@code postcode} the same way {@link #assignHouseholdId} assigns it (see
755	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
756	     * their whole identities match, regardless of the exact input formats.
757	     *
758	     * @param lastName  the owner's last name
759	     * @param postcode  the owner's postcode
760	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
761	     * @param email     the owner's email, possibly {@code null}
762	     * @return the canonical identity key
763	     */
764	    private static String identityKeyFor(String lastName, String postcode, String telephone, String email) {
765	        String normalizedTelephone = toE164(telephone);
766	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
767	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
768	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, postcode);
769	    }
770	
771	    /**
772	     * The maximum number of owners permitted in a single city. A create is rejected once the
773	     * owner's city already contains this many owners.
774	     */
775	    private static final long CITY_CAPACITY = 50;
776	
777	    /**
778	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
779	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
780	     * before this owner is persisted.
781	     *
782	     * @param city the submitted city
783	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
784	     */
785	    private void rejectCityAtCapacity(String city) {
786	        long count = this.clinicService.findAllOwners().stream()
787	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
788	            .count();
789	        if (count >= CITY_CAPACITY) {
790	            throw new CityAtCapacityException(city);
791	        }
792	    }
793	
794	    /**
795	     * The maximum number of owners permitted to be created in a single day. A create is
796	     * rejected once this many owners already carry today's {@code registrationDate}.
797	     */
798	    private static final long DAILY_LIMIT = 100;
799	
800	    /**
801	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
802	     * business day as their {@code registrationDate}. The day counted against is this create's
803	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
804	     * so owners are counted per adjusted business day. The count is taken before this owner is
805	     * persisted.
806	     *
807	     * @param businessDay the effective, business-day-adjusted registration date of this create
808	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
809	     */
810	    private void rejectDailyLimit(LocalDate businessDay) {
811	        long count = this.clinicService.findAllOwners().stream()
812	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
813	            .count();
814	        if (count >= DAILY_LIMIT) {
815	            throw new DailyOwnerLimitExceededException(businessDay);
816	        }
817	    }
818	
819	    /**
820	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
821	     * every internal run of whitespace is collapsed to a single space, and the result is
822	     * lower-cased. A {@code null} value collapses to the empty string.
823	     *
824	     * @param value the value to canonicalize, possibly {@code null}
825	     * @return the collapsed, lower-cased value
826	     */
827	    private static String collapse(String value) {
828	        if (value == null) {
829	            return "";
830	        }
831	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
832	    }
833	
834	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
835	    @Override
836	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
837	        Owner owner = this.clinicService.findOwnerById(ownerId);
838	        if (owner != null) {
839	            Pet pet = owner.getPet(petId);
840	            if (pet != null) {
841	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
842	            }
843	        }
844	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
845	    }
846	}
